"use client";

import * as React from "react";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { formFieldBase, formFieldSingleLine } from "./_shared";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "./command";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

const regions = [
  { value: "us-east-1", label: "US East (N. Virginia)" },
  { value: "eu-west-1", label: "EU West (Ireland)" },
  { value: "sa-east-1", label: "South America (São Paulo)" },
  { value: "ap-northeast-1", label: "Asia Pacific (Tokyo)" },
  { value: "ap-southeast-2", label: "Asia Pacific (Sydney)" },
];

/**
 * Ink mail combobox: a field that opens a searchable list of sending
 * regions. The trigger is the dark well every text field uses, with an
 * up-down caret at the end; open, its edge brightens to the off-white ink.
 * The list drops onto the elevated panel, as wide as the trigger, and the
 * chosen row carries a tick.
 */
export function ComboboxDemo() {
  const [open, setOpen] = React.useState(false);
  const [value, setValue] = React.useState("");
  const selected = regions.find((region) => region.value === value);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        role="combobox"
        aria-expanded={open}
        data-slot="combobox-trigger"
        className={cn(
          formFieldBase,
          formFieldSingleLine,
          "w-64 cursor-default items-center justify-between gap-2 text-start",
          "data-[popup-open]:border-foreground",
          !selected && "text-muted-foreground",
        )}
      >
        <span className="truncate">{selected ? selected.label : "Select a region"}</span>
        <Icon
          icon="ph:caret-up-down"
          className="size-4 shrink-0 text-muted-foreground"
          aria-hidden="true"
        />
      </PopoverTrigger>
      <PopoverContent align="start" className="w-(--anchor-width) gap-0 p-0">
        <Command className="bg-transparent shadow-none">
          <CommandInput placeholder="Search regions" />
          <CommandList>
            <CommandEmpty>No region found.</CommandEmpty>
            <CommandGroup>
              {regions.map((region) => (
                <CommandItem
                  key={region.value}
                  value={region.value}
                  onSelect={(currentValue: string) => {
                    setValue(currentValue === value ? "" : currentValue);
                    setOpen(false);
                  }}
                >
                  <span className="truncate">{region.label}</span>
                  <Icon
                    icon="ph:check"
                    className={cn(
                      "ms-auto size-4",
                      value === region.value ? "opacity-100" : "opacity-0",
                    )}
                    aria-hidden="true"
                  />
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
